BEGIN;
SET LOCAL lock_timeout='3s';

-- Exact identity is independent from safety and from whole-label human approval.
CREATE FUNCTION private.material_identity_key(v text) RETURNS text
LANGUAGE sql IMMUTABLE STRICT SET search_path='' AS $$
 SELECT nullif(regexp_replace(translate(lower(replace(replace(normalize(v,NFKC),'가루','분말'),'파우더','분말')),
 '()（）[]{}*·•▪◦・,.。:_-–—/\',''),'\s+','','g'),'')
$$;
CREATE TABLE private.material_identity_terms (
 term text NOT NULL, canonical_id uuid NOT NULL REFERENCES public.canonical_ingredients(id) ON DELETE CASCADE,
 PRIMARY KEY(term,canonical_id)
);
CREATE FUNCTION private.material_identity_strict_key(v text) RETURNS text
LANGUAGE sql IMMUTABLE STRICT SET search_path='' AS $$
 SELECT nullif(regexp_replace(translate(lower(replace(replace(normalize(v,NFKC),'가루','분말'),'파우더','분말')),
 '()（）[]{}*·•▪◦・,',''),'\s+','','g'),'')
$$;
ALTER TABLE private.material_identity_terms ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON private.material_identity_terms FROM PUBLIC,anon,authenticated,service_role;

CREATE FUNCTION private.refresh_material_identity_terms() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE desired jsonb; changed text[];
BEGIN
 PERFORM pg_advisory_xact_lock(hashtextextended('material_identity_terms',0));
 SELECT coalesce(jsonb_agg(to_jsonb(rows)),'[]') INTO desired FROM (SELECT DISTINCT keys.term,c.id canonical_id
 FROM public.canonical_ingredients c
 CROSS JOIN LATERAL (
   SELECT c.canonical_name_ko term UNION ALL SELECT c.canonical_name_en
   UNION ALL SELECT a.alias_text FROM public.canonical_ingredient_aliases a WHERE a.canonical_ingredient_id=c.id
   UNION ALL SELECT unnest(i.aliases) FROM public.ingredients i WHERE i.id=c.legacy_ingredient_id
 ) t CROSS JOIN LATERAL (VALUES
 ('strict:'||private.material_identity_strict_key(t.term)),('loose:'||private.material_identity_key(t.term))) keys(term)
 WHERE c.status='active' AND keys.term IS NOT NULL) rows;
 WITH next_terms AS (SELECT * FROM jsonb_to_recordset(desired) r(term text,canonical_id uuid)),
 delta AS ((SELECT * FROM private.material_identity_terms EXCEPT SELECT * FROM next_terms)
   UNION (SELECT * FROM next_terms EXCEPT SELECT * FROM private.material_identity_terms))
 SELECT array_agg(DISTINCT term) INTO changed FROM delta;
 DELETE FROM private.material_identity_terms;
 INSERT INTO private.material_identity_terms SELECT * FROM jsonb_to_recordset(desired) r(term text,canonical_id uuid);
 IF changed IS NOT NULL AND to_regprocedure('private.reconcile_material_terms(text[])') IS NOT NULL THEN
   PERFORM private.reconcile_material_terms(changed);
 END IF;
 RETURN NULL;
END $$;
CREATE TRIGGER refresh_material_identity_terms AFTER INSERT OR UPDATE OR DELETE ON public.canonical_ingredients
 FOR EACH STATEMENT EXECUTE FUNCTION private.refresh_material_identity_terms();
CREATE TRIGGER refresh_material_identity_terms AFTER INSERT OR UPDATE OR DELETE ON public.canonical_ingredient_aliases
 FOR EACH STATEMENT EXECUTE FUNCTION private.refresh_material_identity_terms();
-- These two missing identities are not interchangeable with generic phosphate
-- or seaweed powder. Caution explicitly covers specification/dose uncertainty.
INSERT INTO public.ingredients(name_ko,name_en,risk_level,description)
VALUES ('해조유','Algal oil','caution','미세조류 유래 유지로 장쇄 오메가3 지방산의 공급원으로 사용됩니다. EPA·DHA 함량은 균주와 원료 규격별로 달라 제품 표시량을 확인해야 합니다.'),
 ('제일인산칼슘','Monocalcium phosphate','caution','칼슘과 인을 공급하는 무기질 원료입니다. 제이·제삼인산칼슘과 구분하며 전체 식단의 칼슘·인 함량과 비율을 함께 확인합니다.')
ON CONFLICT(name_ko) DO NOTHING;

-- Curated identity/role facts; no efficacy, dose adequacy or human approval is implied.
INSERT INTO public.ingredients(name_ko,name_en,category,risk_level,description)
 SELECT f.name,f.english,f.category,f.risk::public.risk_level_enum,f.description FROM jsonb_to_recordset($material_facts$[{"name":"옥수수분말","english":"Ground corn","category":"곡류","risk":"safe","description":"옥수수를 분쇄한 원재료로 전분 공급원이 됩니다. 통곡·글루텐·전분을 분리한 원료와 구분하며 제품의 탄수화물 함량은 별도 표시정보로 확인합니다.","source":"https://www.royalcanin.com/kr/dogs/products/retail-products/mini-indoor-adult-2434"},{"name":"양조효모","english":"Brewers yeast","category":"효모","risk":"safe","description":"양조 과정에서 얻는 효모 원재료입니다. 효모가 표시되었다는 이유만으로 살아 있는 유산균이나 보장된 프로바이오틱 효과로 판정하지 않습니다.","source":"https://www.royalcanin.com/kr/dogs/products/retail-products/mini-indoor-adult-2434"},{"name":"유도 단백질","english":"Protein derivatives","category":"가공 단백질","risk":"caution","description":"가공한 단백질 원료를 나타내는 포괄 표기입니다. 원문에 적힌 동물 출처를 보존하며 가수분해 정도나 알레르기 안전성을 임의로 확정하지 않습니다.","source":"https://www.royalcanin.com/kr/dogs/products/retail-products/mini-indoor-adult-2434"},{"name":"비타민제 합제","english":"Vitamin premix","category":"비타민 혼합물","risk":"safe","description":"비타민 원료를 섞은 복합 원재료 표기입니다. 개별 비타민의 종류·화학형·투입량은 상세 표시를 확인하며 이 표기만으로 비타민 충분량을 판정하지 않습니다.","source":"https://www.royalcanin.com/kr/dogs/products/retail-products/mini-indoor-adult-2434"},{"name":"혼합광물질류 합제","english":"Mineral premix","category":"무기질 혼합물","risk":"safe","description":"여러 무기질 원료를 혼합한 복합 원재료 표기입니다. 원문에 열거된 성분을 보존하되 개별 무기질 함량이나 칼슘:인 비율은 추측하지 않습니다.","source":"https://www.royalcanin.com/kr/dogs/products/retail-products/mini-indoor-adult-2434"},{"name":"글리세린 지방산 에스테르","english":"Glycerol fatty acid esters","category":"기술적 첨가물","risk":"safe","description":"글리세린과 지방산의 에스테르 계열로 유화 등 제품의 물성을 조절하는 데 쓰입니다. 포괄 표기만으로 특정 화합물이나 첨가물 번호·지방 함량을 확정하지 않습니다.","source":"https://data.food.gov.uk/regulated-products/id/food-additives/additive/e-471"},{"name":"산화마그네슘","english":"Magnesium oxide","category":"무기질","risk":"safe","description":"마그네슘을 포함하는 무기질 화합물입니다. 제품 전체의 마그네슘 함량·급여량·건강 상태를 함께 확인하며 화합물 투입량을 원소 마그네슘 함량으로 그대로 계산하지 않습니다.","source":"https://hfpappexternal.fda.gov/scripts/fdcc/index.cfm?id=MAGNESIUMOXIDE&set=FoodSubstances"},{"name":"L-라이신","english":"L-Lysine","category":"아미노산","risk":"safe","description":"라이신을 공급하는 L형 아미노산 원료입니다. 염산염·황산염 등 다른 화학형과 구분하며 첨가 여부만으로 필수 아미노산 충분량이나 단백질 품질을 보장하지 않습니다.","source":"https://joint-research-centre.ec.europa.eu/reports-and-technical-documentation/feed-2024-33300-feed-2024-33438_en"},{"name":"L-타이로신","english":"L-Tyrosine","category":"아미노산","risk":"safe","description":"단백질을 구성하는 아미노산인 타이로신의 L형 원료입니다. 배합량과 전체 아미노산 균형을 별도로 확인하며 이 원료만으로 특정 건강 효과를 보장하지 않습니다.","source":"https://eur-lex.europa.eu/eli/reg_impl/2025/752/oj"},{"name":"제올라이트","english":"Zeolite","category":"기술적 광물 원료","risk":"caution","description":"다공성 알루미노규산염 계열의 포괄 명칭입니다. 고결 방지·흡착 등의 기술적 용도로 사용될 수 있으며 종류·순도·사용량이 다르므로 영양 미네랄이나 장 건강 효과로 단정하지 않습니다.","source":"https://efsa.onlinelibrary.wiley.com/doi/10.2903/j.efsa.2021.6976"},{"name":"폴리인산나트륨","english":"Sodium polyphosphates","category":"인산염계 첨가물","risk":"caution","description":"나트륨을 포함하는 축합 인산염 계열의 표기입니다. 단일 인산염·소금·인산칼슘과 구분하며 구체적인 화합물·함량은 제품 규격을 확인해야 합니다.","source":"https://www.royalcanin.com/kr/dogs/products/retail-products/mini-indoor-adult-2434"}]$material_facts$::jsonb) AS f(name text,english text,category text,risk text,description text,source text) ON CONFLICT(name_ko) DO NOTHING;

CREATE FUNCTION private.sync_material_identity() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
BEGIN
 INSERT INTO public.canonical_ingredients(canonical_name_ko,canonical_name_en,normalized_key,category,description,status,legacy_ingredient_id,identity_key)
 VALUES(NEW.name_ko,NEW.name_en,public.normalize_ingredient_identity(NEW.name_ko),NEW.category,
   'Exact registry identity; nutrient and safety evidence are independent.','active',NEW.id,
   'legacy:'||public.normalize_ingredient_identity(NEW.name_ko)) ON CONFLICT DO NOTHING;
 -- The INSERT statement trigger refreshes terms even on a uniqueness conflict,
 -- so edited legacy aliases participate without a second full rebuild.
 RETURN NULL;
END $$;
CREATE TRIGGER sync_material_identity AFTER INSERT OR UPDATE OF name_ko,name_en,aliases ON public.ingredients
 FOR EACH ROW EXECUTE FUNCTION private.sync_material_identity();
INSERT INTO public.canonical_ingredients(canonical_name_ko,canonical_name_en,normalized_key,category,description,status,legacy_ingredient_id,identity_key)
 SELECT DISTINCT ON (public.normalize_ingredient_identity(i.name_ko))
 i.name_ko,i.name_en,public.normalize_ingredient_identity(i.name_ko),i.category,
 'Exact registry identity; nutrient and safety evidence are independent.','active',i.id,
 'legacy:'||public.normalize_ingredient_identity(i.name_ko)
 FROM public.ingredients i WHERE public.normalize_ingredient_identity(i.name_ko) IS NOT NULL
 ORDER BY public.normalize_ingredient_identity(i.name_ko),length(i.name_ko),i.id ON CONFLICT DO NOTHING;
INSERT INTO public.canonical_ingredient_aliases(canonical_ingredient_id,alias_text,normalized_alias,language_code,alias_type)
 SELECT c.id,a.alias,public.normalize_ingredient_identity(a.alias),'ko','label'
 FROM jsonb_to_recordset($material_aliases$[{"canonical":"셀룰로오스 분말","alias":"분말 셀룰로오스"},{"canonical":"셀룰로오스 분말","alias":"분말셀룰로스"},{"canonical":"동물성지방","alias":"동물성 유지"},{"canonical":"DL-메티오닌","alias":"DL-메치오닌"},{"canonical":"L-타이로신","alias":"L-티로신"},{"canonical":"닭기름 (계유)","alias":"계유"},{"canonical":"인산칼슘 (제이)","alias":"제이인산칼슘"}]$material_aliases$::jsonb) a(canonical text,alias text)
 JOIN public.canonical_ingredients c ON c.canonical_name_ko=a.canonical AND c.status='active'
 ON CONFLICT(normalized_alias,language_code) DO NOTHING;

-- Initialize through the same trigger used for subsequent registry edits.
UPDATE public.canonical_ingredients SET id=id WHERE false;

CREATE FUNCTION private.material_base_text(v text) RETURNS text
LANGUAGE plpgsql IMMUTABLE STRICT SET search_path='' AS $$
DECLARE ch text; depth integer:=0; result text:='';
BEGIN
 FOREACH ch IN ARRAY regexp_split_to_array(normalize(v,NFKC),'') LOOP
   IF ch IN ('(','[','{','【') THEN depth:=depth+1;
   ELSIF ch IN (')',']','}','】') THEN depth:=greatest(0,depth-1);
   ELSIF depth=0 THEN result:=result||ch; END IF;
 END LOOP;
 RETURN btrim(regexp_replace(regexp_replace(result,'[0-9]+(\.[0-9]+)?\s*%','','g'),'\s*(등|외)\s*$',''));
END $$;

CREATE FUNCTION private.match_material_label_item() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE ids uuid[]; full_text text; base_text text;
BEGIN
 IF NEW.match_status='ignored' THEN RETURN NEW; END IF;
 -- Preserve explicit existing resolutions unless the label itself changed or
 -- its definition was retired. Never trust a caller-supplied normalized string.
 IF NEW.match_status='matched' AND (TG_OP='INSERT' OR NEW.raw_ingredient_text IS NOT DISTINCT FROM OLD.raw_ingredient_text)
   AND (EXISTS(SELECT 1 FROM public.canonical_ingredients WHERE id=NEW.canonical_ingredient_id AND status='active')
     OR (NEW.canonical_ingredient_id IS NULL AND EXISTS(SELECT 1 FROM public.ingredients
       WHERE id=NEW.legacy_ingredient_id AND risk_level::text IN ('safe','caution','warning','danger')))) THEN RETURN NEW; END IF;
 full_text:=regexp_replace(NEW.raw_ingredient_text,'[0-9]+(\.[0-9]+)?\s*%','','g');
 base_text:=private.material_base_text(NEW.raw_ingredient_text);
 SELECT array_agg(canonical_id ORDER BY canonical_id) INTO ids FROM private.material_identity_terms
   WHERE term='strict:'||private.material_identity_strict_key(full_text);
 IF ids IS NULL THEN SELECT array_agg(canonical_id ORDER BY canonical_id) INTO ids FROM private.material_identity_terms
   WHERE term='loose:'||private.material_identity_key(full_text); END IF;
 IF ids IS NULL THEN SELECT array_agg(canonical_id ORDER BY canonical_id) INTO ids FROM private.material_identity_terms
   WHERE term='strict:'||private.material_identity_strict_key(base_text); END IF;
 IF ids IS NULL THEN SELECT array_agg(canonical_id ORDER BY canonical_id) INTO ids FROM private.material_identity_terms
   WHERE term='loose:'||private.material_identity_key(base_text); END IF;
 NEW.normalized_ingredient_text:=private.material_identity_key(base_text);
 NEW.canonical_ingredient_id:=CASE WHEN cardinality(ids)=1 THEN ids[1] END;
 NEW.legacy_ingredient_id:=NULL;
 NEW.match_status:=CASE WHEN cardinality(ids)=1 THEN 'matched' WHEN cardinality(ids)>1 THEN 'ambiguous' ELSE 'unmatched' END;
 NEW.match_confidence:=CASE WHEN cardinality(ids)=1 THEN 1 END;
 NEW.parser_metadata:=coalesce(NEW.parser_metadata,'{}')||jsonb_build_object('identityEngine','exact-material-v1','candidateCanonicalIds',coalesce(to_jsonb(ids),'[]'));
 RETURN NEW;
END $$;
CREATE TRIGGER auto_match_material BEFORE INSERT OR UPDATE ON public.product_ingredient_label_items
 FOR EACH ROW EXECUTE FUNCTION private.match_material_label_item();

-- Normalized graph: a raw material -> constituent -> nutritional measure.
-- A qualitative edge is deliberately not a recipe amount or product guarantee.
CREATE TABLE public.nutrient_definitions (
 code text PRIMARY KEY, name_ko text NOT NULL, dimension text NOT NULL CHECK(dimension IN ('mass','energy','activity')),
 definition text NOT NULL
);
CREATE TABLE public.constituent_definitions (
 code text PRIMARY KEY, name_ko text NOT NULL,
 nutrient_code text NOT NULL REFERENCES public.nutrient_definitions(code),
 interpretation text NOT NULL
);
CREATE TABLE public.material_constituent_evidence (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
 canonical_ingredient_id uuid NOT NULL REFERENCES public.canonical_ingredients(id) ON DELETE CASCADE,
 constituent_code text NOT NULL REFERENCES public.constituent_definitions(code),
 relation text NOT NULL CHECK(relation IN ('contains','source_of')),
 source_url text NOT NULL CHECK(source_url ~ '^https://'), source_version text NOT NULL CHECK(length(btrim(source_version))>0),
 source_locator text NOT NULL, note text NOT NULL,
 amount numeric CHECK(amount>=0 AND amount::text NOT IN ('NaN','Infinity','-Infinity')), unit text CHECK(unit IN ('g/100g','mg/kg')),
 basis text CHECK(basis IN ('as_fed','dry_matter')),
 CHECK((amount IS NULL AND unit IS NULL AND basis IS NULL) OR (amount IS NOT NULL AND unit IS NOT NULL AND basis IS NOT NULL)),
 CHECK(amount IS NULL OR (unit='g/100g' AND amount<=100) OR (unit='mg/kg' AND amount<=1000000)),
 UNIQUE(canonical_ingredient_id,constituent_code,source_url,source_version)
);
CREATE INDEX material_constituent_evidence_constituent ON public.material_constituent_evidence(constituent_code);

CREATE TABLE public.product_nutrient_evidence (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(), product_id uuid NOT NULL REFERENCES public.products(id) ON DELETE CASCADE,
 nutrient_code text NOT NULL REFERENCES public.nutrient_definitions(code),
 value numeric NOT NULL CHECK(value>=0 AND value::text NOT IN ('NaN','Infinity','-Infinity')), unit text NOT NULL CHECK(unit IN ('g/100g','mg/kg','kcal/100g','kcal/kg')),
 basis text NOT NULL CHECK(basis IN ('as_fed','dry_matter','per_energy','unspecified')),
 qualifier text NOT NULL CHECK(qualifier IN ('minimum','maximum','typical','exact','unspecified')),
 source_url text NOT NULL CHECK(source_url ~ '^https://'), source_version text NOT NULL,
 source_locator text NOT NULL, captured_at timestamptz NOT NULL DEFAULT now(),
 CHECK(unit<>'g/100g' OR value<=100), CHECK(unit<>'mg/kg' OR value<=1000000),
 UNIQUE(product_id,nutrient_code,source_url,source_version,source_locator)
);
CREATE INDEX product_nutrient_evidence_nutrient ON public.product_nutrient_evidence(nutrient_code);
CREATE FUNCTION private.validate_nutrient_measurement_unit() RETURNS trigger
LANGUAGE plpgsql SET search_path='' AS $$
DECLARE dimension text;
BEGIN
 SELECT n.dimension INTO dimension FROM public.nutrient_definitions n WHERE n.code=NEW.nutrient_code;
 IF (dimension='mass' AND NEW.unit NOT IN ('g/100g','mg/kg'))
   OR (dimension='energy' AND NEW.unit NOT IN ('Mcal/kg','kcal/100g','kcal/kg'))
   OR (dimension='activity' AND NEW.unit<>'1000IU/kg') OR NEW.basis='per_energy' THEN
   RAISE EXCEPTION 'nutrient_unit_basis_mismatch' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END $$;
CREATE TRIGGER validate_nutrient_measurement_unit BEFORE INSERT OR UPDATE ON public.product_nutrient_evidence
 FOR EACH ROW EXECUTE FUNCTION private.validate_nutrient_measurement_unit();
DO $$ DECLARE t text; BEGIN
 FOREACH t IN ARRAY ARRAY['nutrient_definitions','constituent_definitions','material_constituent_evidence','product_nutrient_evidence'] LOOP
   EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY',t);
   EXECUTE format('REVOKE ALL ON public.%I FROM PUBLIC,anon,authenticated',t);
   EXECUTE format('GRANT SELECT ON public.%I TO anon,authenticated',t);
   EXECUTE format('GRANT ALL ON public.%I TO service_role',t);
   IF t='product_nutrient_evidence' THEN
     EXECUTE 'CREATE POLICY public_product_nutrient_read ON public.product_nutrient_evidence FOR SELECT TO anon,authenticated USING(EXISTS(SELECT 1 FROM public.products p WHERE p.id=product_id))';
   ELSE EXECUTE format('CREATE POLICY public_registry_read ON public.%I FOR SELECT TO anon,authenticated USING(true)',t); END IF;
 END LOOP;
END $$;

