-- Existing numeric label data is retained with its source and an explicit
-- unspecified qualifier: historic rows did not store min/max/typical metadata.
CREATE FUNCTION private.sync_product_nutrient_evidence() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE pid uuid; source text; profile jsonb;
BEGIN
 pid:=CASE WHEN TG_OP='DELETE' THEN OLD.product_id ELSE NEW.product_id END;
 DELETE FROM public.product_nutrient_evidence WHERE product_id=pid AND source_version='profile-projection-v1';
 IF TG_OP='DELETE' THEN RETURN NULL; END IF;
 SELECT catalog_source_url INTO source FROM public.products WHERE id=pid;
 IF source IS NULL OR source !~ '^https://' THEN RETURN NULL; END IF;
 profile:=to_jsonb(NEW);
 INSERT INTO public.product_nutrient_evidence(product_id,nutrient_code,value,unit,basis,qualifier,source_url,source_version,source_locator)
 SELECT pid,m.code,(profile->>m.field)::numeric,'g/100g','as_fed','unspecified',source,'profile-projection-v1','nutritional_profiles.'||m.field
 FROM (VALUES('protein','crude_protein'),('fat','crude_fat'),('crude_fiber','crude_fiber'),('ash','crude_ash'),
   ('moisture','moisture'),('calcium','calcium'),('phosphorus','phosphorus')) m(code,field)
 WHERE profile->>m.field IS NOT NULL AND (profile->>m.field)::numeric BETWEEN 0 AND 100;
 RETURN NULL;
END $$;
CREATE TRIGGER sync_product_nutrient_evidence AFTER INSERT OR UPDATE OR DELETE ON public.nutritional_profiles
 FOR EACH ROW EXECUTE FUNCTION private.sync_product_nutrient_evidence();
UPDATE public.nutritional_profiles SET product_id=product_id;

CREATE FUNCTION public.material_profile(material public.canonical_ingredients) RETURNS jsonb
LANGUAGE sql STABLE SECURITY INVOKER SET search_path='' AS $$
 SELECT coalesce(jsonb_agg(jsonb_build_object('constituentCode',d.code,'constituentName',d.name_ko,
   'nutrientCode',n.code,'nutrientName',n.name_ko,'relation',e.relation,'sourceUrl',e.source_url,
   'sourceVersion',e.source_version,'amount',e.amount,'unit',e.unit,'basis',e.basis) ORDER BY d.code,e.id),'[]')
 FROM public.material_constituent_evidence e JOIN public.constituent_definitions d ON d.code=e.constituent_code
 JOIN public.nutrient_definitions n ON n.code=d.nutrient_code WHERE e.canonical_ingredient_id=material.id
$$;
CREATE FUNCTION public.material_profile(material public.ingredients) RETURNS jsonb
LANGUAGE sql STABLE SECURITY INVOKER SET search_path='' AS $$
 SELECT coalesce((SELECT public.material_profile(c) FROM public.canonical_ingredients c
 WHERE c.legacy_ingredient_id=material.id AND c.status='active' ORDER BY c.id LIMIT 1),'[]')
$$;
REVOKE ALL ON FUNCTION public.material_profile(public.canonical_ingredients),public.material_profile(public.ingredients) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.material_profile(public.canonical_ingredients),public.material_profile(public.ingredients) TO anon,authenticated,service_role;

CREATE FUNCTION private.recompute_material_readiness() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE pid uuid; unresolved integer; item_count integer; ambiguous integer; label_id uuid;
BEGIN
 label_id:=CASE WHEN TG_OP='DELETE' THEN OLD.label_set_id ELSE NEW.label_set_id END;
 SELECT product_id INTO pid FROM public.product_ingredient_label_sets WHERE id=label_id AND is_current;
 IF pid IS NULL THEN RETURN NULL; END IF;
 SELECT count(*),count(*) FILTER(WHERE i.match_status<>'matched' OR (i.canonical_ingredient_id IS NOT NULL AND c.status IS DISTINCT FROM 'active')
   OR g.risk_level::text NOT IN ('safe','caution','warning','danger') OR g.id IS NULL)
 ,count(*) FILTER(WHERE i.match_status='ambiguous') INTO item_count,unresolved,ambiguous FROM public.product_ingredient_label_items i
 LEFT JOIN public.canonical_ingredients c ON c.id=i.canonical_ingredient_id
 LEFT JOIN public.ingredients g ON g.id=coalesce(i.legacy_ingredient_id,c.legacy_ingredient_id)
 WHERE i.label_set_id=label_id AND i.match_status<>'ignored';
 UPDATE public.products SET analysis_status=CASE WHEN item_count=0 THEN 'unavailable'
   WHEN ambiguous>0 THEN 'blocked' WHEN unresolved=0 THEN 'ready' ELSE 'partial' END
 WHERE id=pid AND analysis_status IS DISTINCT FROM CASE WHEN item_count=0 THEN 'unavailable'
   WHEN ambiguous>0 THEN 'blocked' WHEN unresolved=0 THEN 'ready' ELSE 'partial' END;
 RETURN NULL;
END $$;
CREATE TRIGGER recompute_material_readiness AFTER INSERT OR UPDATE OR DELETE ON public.product_ingredient_label_items
 FOR EACH ROW EXECUTE FUNCTION private.recompute_material_readiness();

-- The older ingestion RPC writes "partial" unconditionally at its end. Resolve
-- readiness from the stored current rows, including that final write.
CREATE FUNCTION private.enforce_material_readiness() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE n integer; missing integer; ambiguous integer;
BEGIN
 IF NEW.analysis_status='blocked' THEN RETURN NEW; END IF;
 SELECT count(*),count(*) FILTER(WHERE i.match_status<>'matched'
   OR (i.canonical_ingredient_id IS NOT NULL AND c.status IS DISTINCT FROM 'active')
   OR g.id IS NULL OR g.risk_level::text NOT IN ('safe','caution','warning','danger'))
 ,count(*) FILTER(WHERE i.match_status='ambiguous') INTO n,missing,ambiguous FROM public.product_ingredient_label_sets l
 JOIN public.product_ingredient_label_items i ON i.label_set_id=l.id
 LEFT JOIN public.canonical_ingredients c ON c.id=i.canonical_ingredient_id
 LEFT JOIN public.ingredients g ON g.id=coalesce(i.legacy_ingredient_id,c.legacy_ingredient_id)
 WHERE l.product_id=NEW.id AND l.is_current AND i.match_status<>'ignored';
 IF EXISTS(SELECT 1 FROM public.product_ingredient_label_sets WHERE product_id=NEW.id AND is_current) THEN
   NEW.analysis_status:=CASE WHEN n=0 THEN 'unavailable' WHEN ambiguous>0 THEN 'blocked' WHEN missing=0 THEN 'ready' ELSE 'partial' END;
 END IF;
 RETURN NEW;
END $$;
CREATE TRIGGER enforce_material_readiness BEFORE UPDATE OF analysis_status ON public.products
 FOR EACH ROW EXECUTE FUNCTION private.enforce_material_readiness();

CREATE FUNCTION private.reconcile_material_terms(terms text[]) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
BEGIN
 UPDATE public.product_ingredient_label_items i SET match_status='unreviewed',canonical_ingredient_id=NULL,legacy_ingredient_id=NULL
 FROM public.product_ingredient_label_sets l WHERE l.id=i.label_set_id AND l.is_current AND i.match_status<>'ignored'
 AND (i.match_status<>'matched' OR i.parser_metadata->>'identityEngine'='exact-material-v1'
   OR NOT EXISTS(SELECT 1 FROM public.canonical_ingredients c WHERE c.id=i.canonical_ingredient_id AND c.status='active'))
 AND (('strict:'||private.material_identity_strict_key(regexp_replace(i.raw_ingredient_text,'[0-9]+(\.[0-9]+)?\s*%','','g')))=ANY(terms)
   OR ('loose:'||private.material_identity_key(regexp_replace(i.raw_ingredient_text,'[0-9]+(\.[0-9]+)?\s*%','','g')))=ANY(terms)
   OR ('strict:'||private.material_identity_strict_key(private.material_base_text(i.raw_ingredient_text)))=ANY(terms)
   OR ('loose:'||private.material_identity_key(private.material_base_text(i.raw_ingredient_text)))=ANY(terms));
END $$;
REVOKE ALL ON FUNCTION private.reconcile_material_terms(text[]) FROM PUBLIC,anon,authenticated,service_role;

-- Backfill only current, unresolved items. Matching does not approve a product,
-- change visibility, or create label-comparison evidence.
UPDATE public.product_ingredient_label_items i SET raw_ingredient_text=i.raw_ingredient_text
 FROM public.product_ingredient_label_sets l WHERE i.label_set_id=l.id AND l.is_current
 AND i.match_status IN ('unreviewed','unmatched','ambiguous');

REVOKE ALL ON FUNCTION private.material_identity_key(text),private.material_base_text(text),
 private.refresh_material_identity_terms(),private.match_material_label_item(),private.recompute_material_readiness(),
 private.sync_material_identity(),private.sync_product_nutrient_evidence(),private.enforce_material_readiness(),private.material_identity_strict_key(text),private.validate_nutrient_measurement_unit()
 FROM PUBLIC,anon,authenticated,service_role;
-- BEGIN GENERATED MATERIAL REFERENCES
-- Quantitative material references use the same canonical identity and nutrient
-- master as qualitative constituent edges. They are never product guarantees.
CREATE TABLE public.material_nutrient_references (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
 canonical_ingredient_id uuid NOT NULL REFERENCES public.canonical_ingredients(id) ON DELETE CASCADE,
 nutrient_code text NOT NULL REFERENCES public.nutrient_definitions(code),
 value numeric NOT NULL CHECK(value>=0 AND value::text NOT IN ('NaN','Infinity','-Infinity')),
 unit text NOT NULL CHECK(unit IN ('g/100g','mg/kg','Mcal/kg','1000IU/kg')),
 basis text NOT NULL CHECK(basis IN ('as_fed','dry_matter')),
 source_url text NOT NULL CHECK(source_url ~ '^https://'), source_version text NOT NULL,
 source_sha256 text NOT NULL CHECK(source_sha256 ~ '^[a-f0-9]{64}$'), source_locator text NOT NULL,
 quality text NOT NULL CHECK(quality IN ('reference','inconsistent')), quality_note text NOT NULL,
 UNIQUE(canonical_ingredient_id,nutrient_code,source_sha256,source_locator)
);
CREATE INDEX material_nutrient_references_nutrient ON public.material_nutrient_references(nutrient_code);
CREATE TRIGGER validate_nutrient_measurement_unit BEFORE INSERT OR UPDATE ON public.material_nutrient_references
 FOR EACH ROW EXECUTE FUNCTION private.validate_nutrient_measurement_unit();
ALTER TABLE public.material_nutrient_references ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.material_nutrient_references FROM PUBLIC,anon,authenticated;
GRANT SELECT ON public.material_nutrient_references TO anon,authenticated;
GRANT ALL ON public.material_nutrient_references TO service_role;
CREATE POLICY public_registry_read ON public.material_nutrient_references FOR SELECT TO anon,authenticated USING(true);
CREATE FUNCTION public.material_nutrient_profile(material public.canonical_ingredients) RETURNS jsonb
LANGUAGE sql STABLE SECURITY INVOKER SET search_path='' AS $$
 SELECT coalesce(jsonb_agg(jsonb_build_object('nutrientCode',n.code,'name',n.name_ko,'value',r.value,
   'unit',r.unit,'basis',r.basis,'sourceUrl',r.source_url,'sourceVersion',r.source_version,
   'sourceSha256',r.source_sha256,'sourceLocator',r.source_locator,'quality',r.quality,'qualityNote',r.quality_note) ORDER BY n.code),'[]')
 FROM public.material_nutrient_references r JOIN public.nutrient_definitions n ON n.code=r.nutrient_code
 WHERE r.canonical_ingredient_id=material.id
$$;
CREATE FUNCTION public.material_nutrient_profile(material public.ingredients) RETURNS jsonb
LANGUAGE sql STABLE SECURITY INVOKER SET search_path='' AS $$
 SELECT coalesce((SELECT public.material_nutrient_profile(c) FROM public.canonical_ingredients c
 WHERE c.legacy_ingredient_id=material.id AND c.status='active' ORDER BY c.id LIMIT 1),'[]')
$$;
REVOKE ALL ON FUNCTION public.material_nutrient_profile(public.canonical_ingredients),public.material_nutrient_profile(public.ingredients) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.material_nutrient_profile(public.canonical_ingredients),public.material_nutrient_profile(public.ingredients) TO anon,authenticated,service_role;

