SELECT c.id,r.nutrient_code,r.value,r.unit,r.basis,'https://www.nongsaro.go.kr/portal/ps/psz/psza/contentMain.ps?menuId=PS03263','repository standard_feed_2022.json','0c6cb581d5f98a1662fa94ed299f967fadf1382cc80293a68c24ef3598b25519',r.source_locator,r.quality,r.quality_note
